PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <http://w3id.org/brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zlabel WHERE {
  ?z a brick:Zone .
  OPTIONAL {?z rdfs:label ?zlabel}
  OPTIONAL {?z brick:hasSubClass rdfs:label}
  FILTER(CONTAINS(str(?z), "Perimeter_mid") || (CONTAINS(str(?zlabel), "Perimeter_mid")))
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?z ?zlabel WHERE {
  ?z a brick:Zone .
  OPTIONAL {?z rdfs:label ?zlabel}
} LIMIT 40

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?zlabel WHERE {
  ?z a brick:Zone ; rdfs:label ?zlabel .
  FILTER(CONTAINS(str(?zlabel), "Perimeter_mid_ZN_4"))
}
